// Normalize input – accepts the JSON body sent by Lovable or scripts/run_demo.py
const raw = $input.first().json;
const b = raw.body ?? raw;
const p = b.project || {};
const input = {
  started_ms: Date.now(),
  project: {
    id: p.id ?? null,
    name: p.name ?? 'Unnamed project',
    company: p.company ?? '',
    client_name: p.client_name ?? '',
    consent_name_allowed: p.consent_name_allowed !== false,
    notes: p.notes ?? '',
  },
  week: b.week ?? '',
  media_url: b.media_url ?? b.video_url ?? b.audio_url ?? '',
  transcript: String(b.transcript ?? '').trim(),
  photo_urls: Array.isArray(b.photo_urls) ? b.photo_urls.slice(0, 8) : [],
  output_language: b.output_language ?? 'en',
  customer_language: b.customer_language ?? b.output_language ?? 'en',
  stt_language: b.stt_language ?? 'ces',
  stt_model: b.stt_model ?? 'scribe_v1',
  model: b.model ?? 'gpt-4o-mini',
};
if (!input.transcript && !input.media_url) {
  throw new Error('Send either "transcript" (text) or "media_url" (public URL of the walk-through video).');
}
input.needs_stt = !input.transcript && !!input.media_url;
return [{ json: input }];

// Turn the ElevenLabs Speech-to-Text response into a timestamped transcript: "[mm:ss] sentence"
const input = $('Normalize input').first().json;
const stt = $input.first().json;
const words = (stt.words || []).filter(w => w.type !== 'spacing' && w.type !== 'audio_event');
const fmt = s => {
  const m = Math.floor(s / 60), ss = Math.floor(s % 60);
  return `[${String(m).padStart(2, '0')}:${String(ss).padStart(2, '0')}]`;
};
const lines = [];
let cur = [], start = null, last = 0;
for (const w of words) {
  const ws = w.start ?? last;
  if (start === null) start = ws;
  if (cur.length && ws - last > 1.2) { // pause = new line
    lines.push(`${fmt(start)} ${cur.join(' ')}`); cur = []; start = ws;
  }
  cur.push(w.text);
  last = w.end ?? ws;
  if (/[.!?]$/.test(w.text) && cur.length > 4) { // sentence end
    lines.push(`${fmt(start)} ${cur.join(' ')}`); cur = []; start = null;
  }
}
if (cur.length) lines.push(`${fmt(start ?? 0)} ${cur.join(' ')}`);
const transcript = lines.length ? lines.join('\n') : String(stt.text || '').trim();
if (!transcript) throw new Error('Speech-to-text returned no text. Check the media_url and the ElevenLabs key.');
return [{ json: { ...input, transcript, stt_language_detected: stt.language_code ?? null } }];

// Build the prompts for the OpenAI nodes: one text call for all outputs, one image call for photo selection
const d = $input.first().json;
const consentRule = d.project.consent_name_allowed
  ? 'The client name MAY be used in the social draft.'
  : 'The client name, address or any identifying detail of the client MUST NOT appear in the social draft. Describe the client generically (e.g. "an engineering company in the Zlín region").';

const system_prompt = `You are the reporting assistant of a Czech construction company in the NWT group (solar power plants, battery storage, buildings).
Every week a site manager records a short walk-through video and describes what was NEWLY BUILT since last week. You get the transcript and the project notes.
Write outputs for the customer, the project chronicle / site inspection meeting, marketing and management.

STRICT RULES
1. Use ONLY facts from the transcript and the project notes. Never invent numbers, dates, names, quotes or technical details.
2. Write every number exactly as it appears in the sources (same digits). If a number is not in the sources, leave it out.
3. Consent: ${consentRule}
4. Factual, friendly, short. No hype words, no emojis in customer_report and project_page_entry.

Return ONLY one JSON object with exactly these keys:
{
  "customer_report": {"subject": string, "body": string},
  "project_page_entry": {"title": string, "body": string},
  "social_draft": {"text_en": string, "text_cs": string, "hashtags": [string]},
  "issues": [{"text": string, "severity": "info" | "warning" | "blocker"}],
  "next_steps": [string]
}
- customer_report: weekly progress e-mail to the client in language "${d.customer_language}", 80-150 words: what was built this week, what comes next, anything the client must do.
- project_page_entry: chronicle entry in language "${d.output_language}", 40-90 words, short lines starting with "- ".
- social_draft: one post for website news / LinkedIn / Instagram, 40-70 words, in English (text_en) and Czech (text_cs), 3-6 hashtags.
- issues: delays, missing material, waiting for the client, safety. Empty list if none.`;

const user_prompt = `Project: ${d.project.name}
Company: ${d.project.company}
Week: ${d.week}

PROJECT NOTES:
${d.project.notes || '(none)'}

TRANSCRIPT OF THIS WEEK'S WALK-THROUGH VIDEO:
${d.transcript}`;

const photo_prompt = `You see ${d.photo_urls.length} photos from a construction site, in this order: index 0 to ${d.photo_urls.length - 1}.
Suggest the 3 best photos for a marketing post, best first (sharp, shows finished or impressive work, no recognisable faces, no readable car number plates). If there are fewer than 3 usable photos, suggest fewer.
photo_flags: list ONLY photos that show a recognisable human face or a readable car number plate. Equipment, buildings and panels are never a reason to flag. If no photo has a face or plate, return an empty list.
Return ONLY JSON: {"suggested": [{"index": number, "reason": string}], "photo_flags": [{"index": number, "reason": string}]}`;

return [{
  json: {
    ...d,
    system_prompt,
    user_prompt,
    photo_prompt,
    has_photos: d.photo_urls.length > 0,
    photo_urls_csv: d.photo_urls.join(','),
  },
}];

// Parse both OpenAI answers and run the guardrails:
// every number must exist in the sources, client-name consent must be respected, flagged photos are never chosen
const d = $('Build prompts').first().json;

const findText = (x) => {
  if (x == null) return null;
  if (Array.isArray(x)) { for (const v of x) { const t = findText(v); if (t != null) return t; } return null; }
  if (typeof x === 'object') {
    if ((x.type === 'output_text' || x.type === undefined) && x.text != null && typeof x.text !== 'undefined') return x.text;
    for (const k of ['output', 'content', 'message', 'choices']) { if (x[k] != null) { const t = findText(x[k]); if (t != null) return t; } }
    return null;
  }
  return null;
};
const toJson = (raw, what) => {
  if (raw && typeof raw === 'object') return raw;
  const s = String(raw ?? '').replace(/^\s*```(?:json)?\s*/i, '').replace(/\s*```\s*$/, '');
  try { return JSON.parse(s); } catch (e) { throw new Error(`${what}: the model did not return valid JSON: ${s.slice(0, 400)}`); }
};

const out = toJson(findText($('Write outputs (OpenAI)').first().json), 'Write outputs');
let photo = { best_photo_index: null, photo_flags: [] };
let photo_error = null;
try {
  const p = $('Pick best photo (OpenAI)').first().json;
  if (p?.error) photo_error = String(p.error?.message ?? p.error);
  const pt = findText(p);
  if (pt != null) photo = toJson(pt, 'Pick best photo');
} catch (e) {
  // photo step did not run (no photos) or failed: the texts are still delivered
  if (!/not executed|hasn't been executed|has not been executed|No node|no data/i.test(String(e.message))) photo_error = String(e.message);
}

// ---- Fact check: numbers -------------------------------------------------
const NUM = /\d+(?:[.,]\d+)?/g;
const variants = (s) => {
  const v = new Set([s, s.replace(/,/g, '.'), s.replace(/,/g, ''), s.replace(/\./g, ',')]);
  const n = parseFloat(s.replace(/,/g, '.'));
  if (!Number.isNaN(n)) v.add(String(n));
  return [...v];
};
// join thousands written with a space ("1 816", Czech style) so they are read as one number
const joinThousands = (t) => String(t).replace(/(\d)[\s\u00a0\u202f](?=\d{3}(?!\d))/g, '$1');
const sourceText = joinThousands([d.transcript, d.project.notes, d.week, d.project.name].join(' '));
const sourceSet = new Set();
for (const m of sourceText.match(NUM) || []) variants(m).forEach((x) => sourceSet.add(x));

const texts = {
  customer_report: `${out.customer_report?.subject ?? ''} ${out.customer_report?.body ?? ''}`,
  project_page_entry: `${out.project_page_entry?.title ?? ''} ${out.project_page_entry?.body ?? ''}`,
  social_en: out.social_draft?.text_en ?? '',
  social_cs: out.social_draft?.text_cs ?? '',
};
const unverified = [];
for (const [field, t] of Object.entries(texts)) {
  for (const m of joinThousands(t).match(NUM) || []) {
    if (/^\d$/.test(m)) continue; // single digits (list numbering) are not checked
    if (!variants(m).some((x) => sourceSet.has(x))) unverified.push({ field, number: m });
  }
}

// ---- Consent check -------------------------------------------------------
const social = `${texts.social_en} ${texts.social_cs}`.toLowerCase();
const client = (d.project.client_name || '').trim().toLowerCase();
const consent_ok = d.project.consent_name_allowed || !client || !social.includes(client);

// ---- Photos --------------------------------------------------------------
const flags = (photo.photo_flags || []).filter((f) => Number.isInteger(f.index));
const flagged = new Set(flags.map((f) => f.index));
// up to 3 suggestions, best first; flagged photos are never suggested; fill up with unflagged photos
const legacy = Number.isInteger(photo.best_photo_index) ? [{ index: photo.best_photo_index, reason: photo.best_photo_reason ?? '' }] : [];
const suggested = [];
for (const s of [...(photo.suggested || []), ...legacy]) {
  if (Number.isInteger(s.index) && d.photo_urls[s.index] && !flagged.has(s.index) && !suggested.some((x) => x.index === s.index)) suggested.push({ index: s.index, reason: s.reason ?? '', url: d.photo_urls[s.index] });
}
d.photo_urls.forEach((u, i) => { if (suggested.length < 3 && !flagged.has(i) && !suggested.some((x) => x.index === i)) suggested.push({ index: i, reason: 'not ranked', url: u }); });
const suggested_photos = suggested.slice(0, 3);
const best_photo_url = suggested_photos[0]?.url ?? null;

return [{
  json: {
    project_id: d.project.id,
    project_name: d.project.name,
    week: d.week,
    transcript: d.transcript,
    customer_report: out.customer_report ?? null,
    project_page_entry: out.project_page_entry ?? null,
    social_draft: out.social_draft ?? null,
    best_photo_url,
    best_photo_reason: suggested_photos[0]?.reason ?? null,
    suggested_photos,
    photo_error,
    photo_flags: flags.map((f) => ({ ...f, url: d.photo_urls[f.index] ?? null })),
    issues: out.issues || [],
    next_steps: out.next_steps || [],
    fact_check: {
      status: unverified.length === 0 && consent_ok ? 'ok' : 'needs_review',
      unverified_numbers: unverified,
      consent_ok,
      numbers_checked: (Object.values(texts).join(' ').match(NUM) || []).length,
    },
    processing_seconds: Math.round((Date.now() - d.started_ms) / 100) / 10,
  },
}];
